Floater.elements=[];function Floater(options={}){if(!options.template&&!options.content){console.error("No template or content has existed");return}if(options.template&&options.content){options.template=null;console.warn("Both 'content' and 'template' specified, 'content' will be ignored")}if(options.template){this._template=document.querySelector(`#${options.template}`);if(!this._template){console.error("No template has existed");return}}this.opt=Object.assign({content:"",closeMethods:["button","overlay","escape"],destroyOnClose:true,footer:false,cssClass:[],lockScroll:true},options);this._content=this.opt.content;this._allowButtonClose=this.opt.closeMethods.includes("button");this._allowBackdropClose=this.opt.closeMethods.includes("overlay");this._allowEscapeClose=this.opt.closeMethods.includes("escape");this._footerButtons=[];this._escape=this._escape.bind(this)}Floater.prototype._hasScrollBar=function(){return document.documentElement.scrollHeight>document.documentElement.clientHeight||document.body.scrollHeight>document.body.clientHeight};Floater.prototype._getScrollbarWidth=function(){if(this._scrollbarWidth)return this._scrollbarWidth;const scrollDiv=document.createElement("div");scrollDiv.style.overflow="scroll";scrollDiv.style.position="absolute";scrollDiv.style.top="-9999px";document.body.appendChild(scrollDiv);this._scrollbarWidth=scrollDiv.offsetWidth-scrollDiv.clientWidth;document.body.removeChild(scrollDiv);return this._scrollbarWidth};Floater.prototype._escape=function(e){if(e.key==="Escape"&&this===Floater.elements[Floater.elements.length-1]){console.log(this._allowEscapeClose);this.close()}};Floater.prototype._build=function(){const contentNode=this._content?document.createElement("div"):this._template.content.cloneNode(true);if(this._content){contentNode.innerHTML=this._content}this._backdrop=document.createElement("div");this._backdrop.className="floater__backdrop";const container=document.createElement("div");container.className="floater__container";this._modalContent=document.createElement("div");this._modalContent.className="floater__content";if(this.opt.cssClass.length){this.opt.cssClass.forEach(elem=>{if(typeof elem==="string"){container.classList.add(elem)}})}this._modalContent.append(contentNode);if(this._allowButtonClose){const close=this._createButton("&times;","floater__close",()=>{this.close()});container.append(close)}container.append(this._modalContent);if(this.opt.footer){this._modalFooter=document.createElement("div");this._modalFooter.className="floater__footer";container.append(this._modalFooter);if(this._footerContent){this._modalFooter.innerHTML=this._footerContent}if(this._footerButtons.length){this._footerButtons.forEach(button=>{this._modalFooter.append(button)})}}this._backdrop.append(container);document.body.append(this._backdrop)};Floater.prototype.setModalContent=function(html){this._content=html;if(this._modalContent){this._modalContent.innerHTML=this._content}};Floater.prototype.setFooterContent=function(html){this._footerContent=html;if(this._modalFooter){this._modalFooter.innerHTML=html}};Floater.prototype.addFooterButton=function(title="",buttonClass="",callback){if(typeof title!=="string"||typeof buttonClass!=="string"||typeof callback!=="function"){console.error("Not right parameter(s)");return}const button=this._createButton(title,buttonClass,callback);this._footerButtons.push(button);if(this._modalFooter){this._footerButtons.forEach(button=>{this._modalFooter.append(button)})}};Floater.prototype._createButton=function(title,buttonClass,callback){const button=document.createElement("button");button.className=buttonClass;button.innerHTML=title;button.onclick=callback;return button};Floater.prototype.open=function(){if(!document.body.contains(this._backdrop)){this._build()}setTimeout(()=>{this._backdrop.classList.add("floater--show")});if(this._allowBackdropClose){this._backdrop.onclick=e=>{if(e.target===this._backdrop){this.close()}}}if(this._allowEscapeClose){document.addEventListener("keydown",this._escape)}if(this.opt.lockScroll){document.body.classList.add("floater--no-scroll");document.body.style.paddingRight=this._getScrollbarWidth()+"px"}if(typeof this.opt.onOpen==="function")this.opt.onOpen();Floater.elements.push(this);return this._backdrop};Floater.prototype.close=function(destroy=this.opt.destroyOnClose){Floater.elements.pop();setTimeout(()=>{this._backdrop.classList.remove("floater--show")});if(!Floater.elements.length){document.body.classList.remove("floater--no-scroll");document.body.style.paddingRight=""}if(typeof this.opt.onClose==="function")this.opt.onClose();this._backdrop.ontransitionend=e=>{if(e.propertyName!=="transform")return;if(destroy){this._backdrop.remove()}document.removeEventListener("keydown",this._escape)}};Floater.prototype.destroy=function(){this.close(true)};